//! Offline acceptance tests for the actual Claude Code, Codex, and `OpenCode`
//! binaries.
//!
//! Recorded fixtures remain the fast compatibility suite. This tier catches
//! the other half of client drift: whether the current executable still reads
//! the configuration written by `with-router` and emits the native request we
//! expect. Every model and Router endpoint used here is a loopback mock and
//! every answer is synthetic, so this never needs a vendor credential or
//! performs paid inference.

/// The pinned 2.1.265 baseline, or the newer release CI installs to prove
/// that Router does not depend on the baseline being the newest client
/// (issue #609). It is a tested version, not a supported maximum.

const CLAUDE_VERSION: &str = match option_env!("ROUTER_REAL_CLIENT_CLAUDE_VERSION") {
    Some(version) => version,
    None => "2.1.265",
};

const CODEX_VERSION: &str = match option_env!("ROUTER_REAL_CLIENT_CODEX_VERSION") {
    Some(version) => version,
    None => "0.154.0",
};

const OPENCODE_VERSION: &str = match option_env!("ROUTER_REAL_CLIENT_OPENCODE_VERSION") {
    Some(version) => version,
    None => "1.18.29",
};

impl CapturedRequest {
    fn header(&self, name: &str) -> Option<&str> {
        self.headers
            .iter()
            .find(|(candidate, _)| candidate.eq_ignore_ascii_case(name))
            .map(|(_, value)| value.as_str())
    }

    fn decoded_body(&self) -> Vec<u8> {
        if self.header("content-encoding").is_some_and(|value| {
            value
                .split(',')
                .any(|encoding| encoding.trim().eq_ignore_ascii_case("zstd"))
        }) {
            zstd::decode_all(self.body.as_slice()).expect("decode captured zstd request")
        } else {
            self.body.clone()
        }
    }

    fn json_body(&self) -> Value {
        serde_json::from_slice(&self.decoded_body()).expect("captured request JSON")
    }
}

struct MockRouter {
    origin: String,
    requests: Arc<Mutex<Vec<CapturedRequest>>>,
    stop: Arc<AtomicBool>,
    thread: Option<thread::JoinHandle<()>>,
}

impl MockRouter {
    fn start(case: ClientCase) -> Self {
        Self::start_with_models(case, default_models(case))
    }

    fn start_with_models(case: ClientCase, models: Vec<Value>) -> Self {
        let listener = TcpListener::bind("127.0.0.1:0").expect("bind offline Router mock");
        listener
            .set_nonblocking(true)
            .expect("configure offline Router mock");
        let address = listener.local_addr().expect("offline Router address");
        let requests = Arc::new(Mutex::new(Vec::new()));
        let captured = Arc::clone(&requests);
        let stop = Arc::new(AtomicBool::new(false));
        let stopped = Arc::clone(&stop);
        let models = Arc::new(models);
        let thread = thread::spawn(move || {
            while !stopped.load(Ordering::Acquire) {
                match listener.accept() {
                    Ok((mut stream, _)) => {
                        let Some(request) = read_request(&mut stream) else {
                            continue;
                        };
                        let response = mock_response(case, &models, &request);
                        captured.lock().expect("capture request").push(request);
                        if let Err(error) = stream.write_all(&response)
                            && !matches!(
                                error.kind(),
                                std::io::ErrorKind::BrokenPipe
                                    | std::io::ErrorKind::ConnectionReset
                                    | std::io::ErrorKind::ConnectionAborted
                            )
                        {
                            panic!("write offline Router response: {error}");
                        }
                    }
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                        thread::sleep(Duration::from_millis(10));
                    }
                    Err(error) => panic!("accept offline Router request: {error}"),
                }
            }
        });
        Self {
            origin: format!("http://{address}"),
            requests,
            stop,
            thread: Some(thread),
        }
    }

    fn inference_request(&self, path: &str) -> Option<CapturedRequest> {
        self.requests
            .lock()
            .expect("read captured requests")
            .iter()
            .find(|request| request.method == "POST" && request.path == path)
            .cloned()
    }

    fn inference_requests(&self, path: &str) -> Vec<CapturedRequest> {
        self.requests
            .lock()
            .expect("read captured requests")
            .iter()
            .filter(|request| request.method == "POST" && request.path == path)
            .cloned()
            .collect()
    }

    fn routes(&self) -> Vec<(String, String)> {
        self.requests
            .lock()
            .expect("read captured request routes")
            .iter()
            .map(|request| (request.method.clone(), request.path.clone()))
            .collect()
    }
}

impl Drop for MockRouter {
    fn drop(&mut self) {
        self.stop.store(true, Ordering::Release);
        let _ = TcpStream::connect(self.origin.trim_start_matches("http://"));
        if let Some(thread) = self.thread.take() {
            thread.join().expect("stop offline Router mock");
        }
    }
}

fn read_request(stream: &mut TcpStream) -> Option<CapturedRequest> {
    stream
        .set_read_timeout(Some(Duration::from_secs(10)))
        .expect("set mock read timeout");
    let mut bytes = Vec::new();
    let mut buffer = [0_u8; 16 * 1024];
    loop {
        let count = match stream.read(&mut buffer) {
            Ok(0) => return None,
            Ok(count) => count,
            Err(error)
                if matches!(
                    error.kind(),
                    std::io::ErrorKind::WouldBlock | std::io::ErrorKind::TimedOut
                ) =>
            {
                return None;
            }
            Err(error) => panic!("read mock request: {error}"),
        };
        bytes.extend_from_slice(&buffer[..count]);
        if request_is_complete(&bytes) {
            break;
        }
    }
    Some(parse_request(&bytes))
}

fn request_is_complete(bytes: &[u8]) -> bool {
    let Some(header_end) = bytes.windows(4).position(|window| window == b"\r\n\r\n") else {
        return false;
    };
    let headers = String::from_utf8_lossy(&bytes[..header_end]);
    if headers
        .lines()
        .next()
        .is_some_and(|line| line.starts_with("GET ") || line.starts_with("DELETE "))
    {
        return true;
    }
    if let Some(length) = headers.lines().find_map(|line| {
        let (name, value) = line.split_once(':')?;
        name.eq_ignore_ascii_case("content-length")
            .then(|| value.trim().parse::<usize>().ok())
            .flatten()
    }) {
        return bytes.len() >= header_end + 4 + length;
    }
    if headers.lines().any(|line| {
        line.split_once(':').is_some_and(|(name, value)| {
            name.eq_ignore_ascii_case("transfer-encoding")
                && value.to_ascii_lowercase().contains("chunked")
        })
    }) {
        return bytes[header_end + 4..]
            .windows(5)
            .any(|window| window == b"0\r\n\r\n");
    }
    true
}

fn parse_request(bytes: &[u8]) -> CapturedRequest {
    let header_end = bytes
        .windows(4)
        .position(|window| window == b"\r\n\r\n")
        .expect("complete HTTP headers");
    let head = String::from_utf8_lossy(&bytes[..header_end]);
    let mut lines = head.lines();
    let mut request_line = lines.next().expect("HTTP request line").split_whitespace();
    let method = request_line.next().expect("HTTP method").to_string();
    let path = request_line
        .next()
        .expect("HTTP request path")
        .split('?')
        .next()
        .expect("path before query")
        .to_string();
    let headers = lines
        .filter_map(|line| {
            line.split_once(':')
                .map(|(name, value)| (name.to_string(), value.trim().to_string()))
        })
        .collect();
    CapturedRequest {
        method,
        path,
        headers,
        body: bytes[header_end + 4..].to_vec(),
    }
}

fn http_response(status: &str, content_type: &str, body: &str) -> Vec<u8> {
    format!(
        "HTTP/1.1 {status}\r\nContent-Type: {content_type}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
        body.len()
    )
    .into_bytes()
}

fn run_token(case: ClientCase) -> String {
    let payload = json!({
        "sub": "offline-run",
        "client_kind": case.client,
        "principal_id": "offline-acceptance"
    });
    let encoded = base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(payload.to_string());
    format!("la_sk_e30.{encoded}.offline-signature")
}

fn default_models(case: ClientCase) -> Vec<Value> {
    if case.client == "codex" {
        vec![
            json!({
                "id": case.model,
                "type": "model",
                "display_name": case.model,
                "created_at": "2026-09-04T00:00:00Z",
                "owned_by": case.owner,
                "default_reasoning_level": "medium",
                "supported_reasoning_levels": [
                    {"effort": "medium", "description": "Balanced reasoning"},
                    {"effort": "high", "description": "Deep reasoning"},
                    {"effort": "xhigh", "description": "Deepest reasoning"}
                ]
            }),
            json!({
                "id": CODEX_ALTERNATE_MODEL,
                "type": "model",
                "display_name": CODEX_ALTERNATE_MODEL,
                "created_at": "2026-09-04T00:00:00Z",
                "owned_by": case.owner,
                "default_reasoning_level": "high",
                "supported_reasoning_levels": [
                    {"effort": "high", "description": "Default reasoning"},
                    {"effort": "xhigh", "description": "Maximum reasoning"}
                ]
            }),
        ]
    } else {
        vec![json!({
            "id": case.model,
            "type": "model",
            "display_name": case.model,
            "created_at": "2026-09-04T00:00:00Z",
            "owned_by": case.owner
        })]
    }
}

fn mock_response(case: ClientCase, models: &[Value], request: &CapturedRequest) -> Vec<u8> {
    match (request.method.as_str(), request.path.as_str()) {
        ("GET", "/api/health") => http_response("200 OK", "application/json", r#"{"status":"ok"}"#),
        ("GET", "/api/management/tokens") => {
            http_response("200 OK", "application/json", r#"{"data":[]}"#)
        }
        ("POST", "/api/management/tokens/client") => http_response(
            "200 OK",
            "application/json",
            &json!({"token": run_token(case)}).to_string(),
        ),
        ("POST", "/api/management/tokens/revoke") => {
            http_response("200 OK", "application/json", r#"{"revoked":"offline-run"}"#)
        }
        ("GET", "/api/services/codex/v1/user-auth-credential/whoami") => http_response(
            "200 OK",
            "application/json",
            r#"{"email":null,"chatgpt_user_id":"usr_offline","chatgpt_account_id":"acct_offline","chatgpt_plan_type":"pro","chatgpt_account_is_fedramp":false}"#,
        ),
        // Codex 0.157+ account discovery lists only whoami's handle (issue #612).
        ("GET", "/api/services/codex/backend-api/wham/accounts/check") => http_response(
            "200 OK",
            "application/json",
            r#"{"accounts":[{"id":"acct_offline","plan_type":"pro","workspace_backend_origin":"https://chatgpt.com","account_routing_override":"NO_CONSTRAINT"}],"account_ordering":["acct_offline"],"default_account_id":"acct_offline"}"#,
        ),
        ("GET", "/api/services/codex/backend-api/plugins/featured") => {
            http_response("200 OK", "application/json", r#"{"plugins":[]}"#)
        }
        ("GET", "/api/models") => http_response(
            "200 OK",
            "application/json",
            &json!({"data": models}).to_string(),
        ),
        ("GET", path) if path == case.catalog_path => {
            let body = match case.client {
                "claude" => {
                    let data = models
                        .iter()
                        .map(|model| {
                            json!({
                            "id": model["id"],
                            "type": "model",
                            "display_name": model["display_name"],
                            "created_at": model["created_at"],
                            })
                        })
                        .collect::<Vec<_>>();
                    json!({
                        "data": data,
                        "has_more": false,
                        "first_id": data.first().and_then(|model| model["id"].as_str()),
                        "last_id": data.last().and_then(|model| model["id"].as_str())
                    })
                }
                "codex" => json!({
                    "models": models.iter().enumerate().map(|(priority, model)| json!({
                        "slug": model["id"],
                        "display_name": model["display_name"],
                        "description": "OpenAI via Link.Assistant.Router",
                        "default_reasoning_level": model["default_reasoning_level"],
                        // Router's own projection: no metadata is an empty list.
                        "supported_reasoning_levels": model.get("supported_reasoning_levels").cloned().unwrap_or_else(|| json!([])),
                        "shell_type": "unified_exec",
                        "visibility": "list",
                        "supported_in_api": true,
                        "priority": priority,
                        "apply_patch_tool_type": "freeform",
                        "truncation_policy": {"mode": "tokens", "limit": 10_000},
                        "base_instructions": ""
                    })).collect::<Vec<_>>()
                }),
                _ => json!({
                    "object": "list",
                    "data": models.iter().map(|model| json!({
                        "id": model["id"],
                        "object": "model",
                    })).collect::<Vec<_>>()
                }),
            };
            http_response("200 OK", "application/json", &body.to_string())
        }
        ("POST", "/api/services/codex/v1/alpha/notes/v2/thread_hint") => http_response(
            "200 OK",
            "application/json",
            r#"{"text":"Synthetic offline history/notes hint."}"#,
        ),
        ("POST", path) if path.ends_with("/messages/count_tokens") => {
            http_response("200 OK", "application/json", r#"{"input_tokens":1}"#)
        }
        ("POST", path) if path == case.inference_path => match case.client {
            "claude" => {
                let model = Some(request.json_body())
                    .and_then(|body| body["model"].as_str().map(str::to_string))
                    .unwrap_or_else(|| case.model.to_string());
                anthropic_mock::catalog_answer(&model, &request.body, models)
            }
            "codex" => {
                let model = Some(request.json_body())
                    .and_then(|body| {
                        body.get("model")
                            .and_then(Value::as_str)
                            .map(str::to_string)
                    })
                    .unwrap_or_else(|| case.model.to_string());
                responses_answer(&model)
            }
            "opencode" => chat_answer(case.model, &request.body),
            other => panic!("no offline answer for {other}"),
        },
        _ => http_response(
            "404 Not Found",
            "application/json",
            &json!({"error": {"message": format!("unexpected offline path {}", request.path)}})
                .to_string(),
        ),
    }
}

fn responses_answer(model: &str) -> Vec<u8> {
    let output = json!({
        "id": "msg_offline",
        "type": "message",
        "status": "completed",
        "role": "assistant",
        "content": [{"type":"output_text", "text":ANSWER, "annotations":[]}]
    });
    let response = json!({
        "id": "resp_offline",
        "object": "response",
        "status": "completed",
        "model": model,
        "output": [output],
        "usage": {"input_tokens":1, "output_tokens":1, "total_tokens":2}
    });
    let events = [
        json!({"type":"response.created", "response":{"id":"resp_offline", "status":"in_progress", "model":model, "output":[]}}),
        json!({"type":"response.output_item.added", "output_index":0, "item":{"id":"msg_offline", "type":"message", "status":"in_progress", "role":"assistant", "content":[]}}),
        json!({"type":"response.content_part.added", "item_id":"msg_offline", "output_index":0, "content_index":0, "part":{"type":"output_text", "text":"", "annotations":[]}}),
        json!({"type":"response.output_text.delta", "item_id":"msg_offline", "output_index":0, "content_index":0, "delta":ANSWER}),
        json!({"type":"response.output_text.done", "item_id":"msg_offline", "output_index":0, "content_index":0, "text":ANSWER}),
        json!({"type":"response.content_part.done", "item_id":"msg_offline", "output_index":0, "content_index":0, "part":{"type":"output_text", "text":ANSWER, "annotations":[]}}),
        json!({"type":"response.output_item.done", "output_index":0, "item":output}),
        json!({"type":"response.completed", "response":response}),
    ];
    let mut body = String::new();
    for value in events {
        let event = value["type"].as_str().expect("response event type");
        write!(&mut body, "event: {event}\ndata: {value}\n\n").expect("write event stream");
    }
    body.push_str("data: [DONE]\n\n");
    http_response("200 OK", "text/event-stream", &body)
}

fn chat_answer(model: &str, request_body: &[u8]) -> Vec<u8> {
    let streamed = serde_json::from_slice::<Value>(request_body)
        .ok()
        .and_then(|value| value.get("stream").and_then(Value::as_bool))
        .unwrap_or(false);
    if streamed {
        let first = json!({
            "id":"chatcmpl-offline", "object":"chat.completion.chunk", "created":0,
            "model":model, "choices":[{"index":0, "delta":{"role":"assistant", "content":ANSWER}, "finish_reason":null}]
        });
        let last = json!({
            "id":"chatcmpl-offline", "object":"chat.completion.chunk", "created":0,
            "model":model, "choices":[{"index":0, "delta":{}, "finish_reason":"stop"}]
        });
        return http_response(
            "200 OK",
            "text/event-stream",
            &format!("data: {first}\n\ndata: {last}\n\ndata: [DONE]\n\n"),
        );
    }
    let body = json!({
        "id":"chatcmpl-offline", "object":"chat.completion", "created":0, "model":model,
        "choices":[{"index":0, "message":{"role":"assistant", "content":ANSWER}, "finish_reason":"stop"}],
        "usage":{"prompt_tokens":1, "completion_tokens":1, "total_tokens":2}
    });
    http_response("200 OK", "application/json", &body.to_string())
}

fn run_wrapper(case: ClientCase, working_directory: &Path, home: &Path, server: &str) -> Output {
    run_wrapper_with_model(case, working_directory, home, server, case.model)
}

fn run_wrapper_with_model(
    case: ClientCase,
    working_directory: &Path,
    home: &Path,
    server: &str,
    model: &str,
) -> Output {
    run_wrapper_with_options(
        case,
        working_directory,
        home,
        server,
        Some(model),
        &[PROMPT],
    )
}

fn assert_real_client_capture(case: ClientCase) {
    if !enabled() {
        return;
    }
    assert!(
        command_exists(case.executable),
        "{} is required when ROUTER_REAL_CLIENT_TESTS=1",
        case.executable
    );
    let directory = tempfile::tempdir().expect("temporary real-client home");
    let foreign_codex_config = if case.client == "codex" {
        let codex_home = directory.path().join(".codex");
        std::fs::create_dir_all(&codex_home).expect("create temporary Codex home");
        let foreign_catalog = codex_home.join("foreign-models.json");
        std::fs::write(
            &foreign_catalog,
            json!({"models": [{"slug": "static-foreign-model", "display_name": "static"}]})
                .to_string(),
        )
        .expect("write foreign Codex catalog");
        let config = codex_home.join("config.toml");
        let contents = format!(
            "model_catalog_json = {:?}\nmodel_reasoning_effort = \"xhigh\"\n\n[mcp_servers.keep]\ncommand = \"kept-mcp\"\n",
            foreign_catalog.to_string_lossy()
        );
        std::fs::write(&config, &contents).expect("write foreign Codex config");
        Some((config, contents.into_bytes()))
    } else {
        None
    };
    let version = version_output(case, directory.path());
    assert!(
        version.status.success(),
        "{} --version failed: {}",
        case.executable,
        String::from_utf8_lossy(&version.stderr)
    );
    let rendered_version = format!(
        "{}{}",
        String::from_utf8_lossy(&version.stdout),
        String::from_utf8_lossy(&version.stderr)
    );
    assert!(
        rendered_version.contains(case.version),
        "expected {} {}, got {rendered_version:?}",
        case.executable,
        case.version
    );

    let router = MockRouter::start(case);
    let output = run_wrapper(
        case,
        Path::new(env!("CARGO_MANIFEST_DIR")),
        directory.path(),
        &router.origin,
    );
    assert!(
        output.status.success(),
        "{} failed against the offline mock; stdout: {}; stderr: {}",
        case.client,
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    assert!(
        String::from_utf8_lossy(&output.stdout).contains(ANSWER),
        "{} did not print the synthetic answer; stdout: {}",
        case.client,
        String::from_utf8_lossy(&output.stdout)
    );
    let catalogs = {
        let requests = router.requests.lock().expect("read catalog requests");
        requests
            .iter()
            .filter(|request| request.method == "GET" && request.path.ends_with("/models"))
            .map(|request| request.path.clone())
            .collect::<Vec<_>>()
    };
    assert!(
        catalogs.iter().any(|path| path == "/api/models"),
        "{} did not discover its client-scoped normalized catalog: {catalogs:?}",
        case.client
    );
    assert!(
        catalogs
            .iter()
            .all(|path| path == "/api/models" || path == case.catalog_path),
        "{} crossed into a different protocol catalog: {catalogs:?}",
        case.client
    );
    if case.client == "codex" {
        let switched = run_wrapper_with_model(
            case,
            Path::new(env!("CARGO_MANIFEST_DIR")),
            directory.path(),
            &router.origin,
            CODEX_ALTERNATE_MODEL,
        );
        assert!(
            switched.status.success(),
            "Codex model switch failed against the offline mock; stdout: {}; stderr: {}",
            String::from_utf8_lossy(&switched.stdout),
            String::from_utf8_lossy(&switched.stderr)
        );
    }
    if case.client == "claude" {
        claude_selector::assert_split_auth_boundary(directory.path(), &router);
    }
    if let Some((config, before)) = foreign_codex_config {
        assert_eq!(
            std::fs::read(config).expect("read Codex config after run"),
            before,
            "with codex must neutralize the foreign catalog only in the child process"
        );
    }

    let deadline = Instant::now() + Duration::from_secs(2);
    let request = loop {
        if let Some(request) = router.inference_request(case.inference_path) {
            break request;
        }
        assert!(
            Instant::now() < deadline,
            "{} never reached {}",
            case.client,
            case.inference_path
        );
        thread::sleep(Duration::from_millis(10));
    };
    assert_eq!(request.method, "POST");
    assert!(
        request.header("user-agent").is_some_and(|value| value
            .strip_prefix(case.user_agent_prefix)
            .is_some_and(|version| version.starts_with(case.version))),
        "unexpected {} user-agent: {:?}",
        case.client,
        request.header("user-agent")
    );
    let token = if case.client == "codex" {
        run_token(case).replacen("la_sk_", "at-", 1)
    } else {
        run_token(case)
    };
    let expected_credential = if case.credential_header == "authorization" {
        format!("Bearer {token}")
    } else {
        token
    };
    assert_eq!(
        request.header(case.credential_header),
        Some(expected_credential.as_str()),
        "{} did not use its native credential carrier",
        case.client
    );
    assert!(
        request
            .headers
            .iter()
            .all(|(name, _)| !name.to_ascii_lowercase().starts_with("x-router")),
        "the real client unexpectedly emitted an internal Router header"
    );
    let decoded = request.decoded_body();
    let body: Value = serde_json::from_slice(&decoded)
        .unwrap_or_else(|error| panic!("{} sent invalid JSON ({error})", case.client));
    assert_eq!(body["model"], case.model);
    assert!(
        String::from_utf8_lossy(&decoded).contains(PROMPT),
        "{} request omitted the prompt",
        case.client
    );
    match case.client {
        "claude" => assert_eq!(request.header("anthropic-version"), Some("2023-06-01")),
        "codex" => {
            assert_eq!(request.header("chatgpt-account-id"), Some("acct_offline"));
            assert_eq!(request.header("originator"), Some("codex_exec"));
            assert!(request.header("x-codex-turn-metadata").is_some());
            let requests = router.inference_requests(case.inference_path);
            assert_eq!(
                requests.len(),
                2,
                "expected one request for each live model"
            );
            let bodies = requests
                .iter()
                .map(CapturedRequest::json_body)
                .collect::<Vec<_>>();
            assert_eq!(bodies[0]["model"], case.model);
            assert_eq!(bodies[1]["model"], CODEX_ALTERNATE_MODEL);
            for body in bodies {
                assert_eq!(
                    body["reasoning"]["effort"], "xhigh",
                    "model selection must preserve the user's explicit reasoning effort"
                );
            }
        }
        "opencode" => {
            assert!(request.header("x-session-id").is_some());
            assert!(request.header("x-session-affinity").is_some());
        }
        _ => unreachable!(),
    }
}

#[test]
fn current_codex_tui_model_selector_preserves_reasoning_effort() {
    if !enabled() {
        return;
    }
    assert!(
        command_exists("codex"),
        "codex is required for the real-client gate"
    );
    let home = tempfile::tempdir().expect("temporary Codex home");
    let codex_home = home.path().join(".codex");
    std::fs::create_dir_all(&codex_home).expect("create Codex home");
    let working_directory = Path::new(env!("CARGO_MANIFEST_DIR"));
    std::fs::write(
        codex_home.join("config.toml"),
        format!(
            "model = {:?}\nmodel_reasoning_effort = \"xhigh\"\n\n[projects.{:?}]\ntrust_level = \"trusted\"\n",
            CODEX.model,
            working_directory.to_string_lossy()
        ),
    )
    .expect("seed Codex settings");

    let router = MockRouter::start(CODEX);
    let mut command = wrapper::isolated_pty_command();
    command.args([
        "--server",
        &router.origin,
        "--token",
        "offline-admin",
        "codex",
    ]);
    command.cwd(working_directory);
    command.env("HOME", home.path());
    command.env("XDG_CONFIG_HOME", home.path().join(".config"));
    command.env("CODEX_HOME", &codex_home);
    command.env("TERM", "xterm-256color");
    command.env("NO_COLOR", "1");
    command.env("NO_PROXY", "127.0.0.1,localhost");
    command.env("no_proxy", "127.0.0.1,localhost");
    command.env("HTTP_PROXY", "http://127.0.0.1:9");
    command.env("HTTPS_PROXY", "http://127.0.0.1:9");
    command.env("ALL_PROXY", "http://127.0.0.1:9");
    let session = PtySession::spawn(command).expect("start Codex TUI through Router");
    session
        .wait_for(
            |text| text.contains(CODEX.model),
            Duration::from_millis(250),
            Duration::from_secs(30),
        )
        .unwrap_or_else(|error| {
            let transcript = session.transcript_tail(2_000);
            // Name the bootstrap capability the client refused, not just the timeout.
            let failure = if transcript.contains("workspace routing discovery") {
                format!("Codex {CODEX_VERSION} refused wham/accounts/check (issue #612)")
            } else {
                format!("Codex TUI did not become ready: {error}")
            };
            panic!(
                "{failure}; routes: {:?}; transcript: {transcript}",
                router.routes()
            )
        });

    session.send_text("/model").expect("type /model");
    session
        .wait_idle(Duration::from_millis(200), Duration::from_secs(3))
        .expect("settle /model input");
    session.send_key(Key::Enter).expect("open model selector");
    session
        .wait_for(
            |text| text.contains(CODEX_ALTERNATE_MODEL),
            Duration::from_millis(250),
            Duration::from_secs(15),
        )
        .unwrap_or_else(|error| {
            panic!(
                "Codex /model did not show the live alternate: {error}; transcript: {}",
                session.transcript_tail(2_000)
            )
        });
    session
        .send_text("\x1b[B")
        .expect("select the next live model");
    session.send_key(Key::Enter).expect("choose selected model");
    session
        .wait_for(
            |text| {
                // The catalog's own xhigh description: Codex 0.157+ redraws
                // only changed cells, so the fixed "Extra high" can be split.
                text.contains(&format!(
                    "Select Reasoning Level for {CODEX_ALTERNATE_MODEL}"
                )) && text.contains("Maximum reasoning")
            },
            Duration::from_millis(250),
            Duration::from_secs(10),
        )
        .unwrap_or_else(|error| {
            panic!(
                "Codex did not expose the alternate model's live effort metadata: {error}; transcript: {}",
                session.transcript_tail(2_000)
            )
        });
    session
        .send_text("\x1b[B")
        .expect("retain the configured extra-high effort");
    session
        .send_key(Key::Enter)
        .expect("confirm model and effort");
    // Codex 0.157+ moves the cursor instead of printing spaces.
    let changed = format!("Modelchangedto{CODEX_ALTERNATE_MODEL}xhigh");
    session
        .wait_for(
            |t| t.split_whitespace().collect::<String>().contains(&changed),
            Duration::from_millis(250),
            Duration::from_secs(10),
        )
        .unwrap_or_else(|error| {
            panic!(
                "Codex did not retain xhigh for the selected model: {error}; transcript: {}",
                session.transcript_tail(2_000)
            )
        });
    session.send_text(PROMPT).expect("type inference prompt");
    session
        .wait_idle(Duration::from_millis(200), Duration::from_secs(3))
        .expect("settle inference prompt");
    session
        .send_key(Key::Enter)
        .expect("submit inference prompt");

    let deadline = Instant::now() + Duration::from_secs(30);
    let request = loop {
        if let Some(request) = router
            .inference_requests(CODEX.inference_path)
            .into_iter()
            .last()
        {
            break request;
        }
        assert!(
            Instant::now() < deadline,
            "Codex TUI never sent the selected-model request; transcript: {}",
            session.transcript_tail(2_000)
        );
        thread::sleep(Duration::from_millis(50));
    };
    let body = request.json_body();
    assert_eq!(body["model"], CODEX_ALTERNATE_MODEL);
    assert_eq!(
        body["reasoning"]["effort"], "xhigh",
        "the /model selector must not reset the configured reasoning effort"
    );
    session.kill();
}

#[test]
fn offline_capture_contracts_are_distinct_and_exact() {
    let cases = [CLAUDE, CODEX, OPENCODE];
    for (index, left) in cases.iter().enumerate() {
        assert!(left.inference_path.starts_with("/api/services/"));
        assert!(!left.model.contains('/'));
        for right in &cases[index + 1..] {
            assert_ne!(left.inference_path, right.inference_path);
            assert_ne!(left.model, right.model);
            assert_ne!(left.credential_header, "x-router-token");
        }
    }
}
